#include <iostream>
#include <algorithm>

using namespace std;

using ll = long long;

ll n;

bool chk(ll k) {
    ll remaining = n;
    ll taken = 0;

    while (remaining > 0) {
        ll current = min(k, remaining);
        taken += current;
        remaining -= current;
        remaining -= remaining / 10;
    }

    return taken >= n / 2 + n % 2;
}

int main() {
    cin >> n;

    ll l = 1, r = n, ans = n;

    while (l <= r) {
        ll mid = l + (r - l) / 2;

        if (chk(mid)) {
            ans = mid;
            r = mid - 1;
        } else {
            l = mid + 1;
        }
    }

    cout << ans;
    return 0;
}

